<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\{Product,StockMovement};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class StockController extends Controller {public function adjust(Request $r,Product $product){abort_unless($r->user()->isAdmin(),403);$v=$r->validate(['quantity_change'=>'required|integer|not_in:0','note'=>'required|string|max:500']);return DB::transaction(function()use($r,$product,$v){$p=Product::lockForUpdate()->findOrFail($product->id);$new=$p->stock+$v['quantity_change'];if($new<0)return response()->json(['success'=>false,'message'=>'Stok tidak boleh negatif'],422);$p->update(['stock'=>$new]);$m=StockMovement::create(['product_id'=>$p->id,'type'=>'ADJUSTMENT','quantity_change'=>$v['quantity_change'],'stock_after'=>$new,'note'=>$v['note'],'created_by'=>$r->user()->id,'created_at'=>now()]);return response()->json(['success'=>true,'message'=>'Adjusted','data'=>$m]);});}public function index(Request $r,Product $product){abort_unless($r->user()->isAdmin(),403);return response()->json(['success'=>true,'message'=>'OK','data'=>$product->movements()->latest('created_at')->paginate(20)]);}}
